using System;using System.Linq;using BeamScheduleFormatter;
class AngleSegmentsTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static void Near(double a,double b,string why){Check(Math.Abs(a-b)<1e-7,why);}static void Reject(Action action,string why){bool rejected=false;try{action();}catch{rejected=true;}Check(rejected,why);}
 static void Main(){var member=new SteelCutDemand{Member="TC",Specification="L75x75x5 | A36",Length=10.322,Quantity=2,KgM=5.7};var segments=AngleSegments.Expand(member,0);Check(segments.Count==2&&member.Joints==1,"10.322m angle is split into two cuts per member");Near(segments[0].Length,6,"First stock-length cut");Near(segments[1].Length,4.322,"Remainder cut");Check(segments.All(s=>s.Quantity==2&&s.Source==member),"Original quantity and source retained independently of segment count");var stock=SteelCutPlanner.Allocate(segments);Check(stock.Count==4,"Two members require four 6m stocks");Near(stock.Sum(s=>s.Remaining),3.356,"Actual final leftover length");Near(SteelCutPlanner.PurchaseKg(stock,member),24*5.7,"Row purchase includes all its segments exactly once");var other=new SteelCutDemand{Member="Short compatible",Specification=member.Specification,Length=1.5,Quantity=2,KgM=5.7};stock=SteelCutPlanner.Allocate(segments.Concat(new[]{other}));Check(stock.Count==4,"Compatible short cuts reuse leftover angle lengths");Near(SteelCutPlanner.PurchaseKg(stock,member)+SteelCutPlanner.PurchaseKg(stock,other),24*5.7,"Shared purchase allocation reconciles to stock mass");other.Specification="L75x75x5 | Different grade";stock=SteelCutPlanner.Allocate(segments.Concat(new[]{other}));Check(stock.Count==5,"Different grade does not share angle stock");segments=AngleSegments.Expand(member,.3);Near(segments.Sum(s=>s.Length),10.622,"Only the explicitly entered extra length is added per joint");Near(segments.Sum(s=>s.Length*s.Quantity),21.244,"Splice addition and member quantity multiplied once");var longMember=new SteelCutDemand{Member="Long",Specification=member.Specification,Length=18,Quantity=1,KgM=5.7};segments=AngleSegments.Expand(longMember,.3);Check(segments.Count==4&&segments.All(s=>s.Length<=6),"Additional splice length can require another segment");Near(segments.Sum(s=>s.Length),18.9,"Three joints contribute three specified allowances");Reject(()=>AngleSegments.Expand(member,6),"Extra length must leave positive progress per stock");Reject(()=>AngleSegments.Expand(member,-.1),"Negative splice addition rejected");Console.WriteLine("PASS: "+checks+" 6m angle segmentation, compatible offcuts, stock mass and explicit splice checks");}
}
